"""Fresh code and delta designs. Each deck branch specifies geometry, not colour substitution."""
from pathlib import Path
from html import escape
import json
R=Path('/workspace/work/rebuild')
NAMES=['tide-tab','cutfield','filament','portico','toggle-grid','lamella','rulemark']
DESC={
 'tide-tab':'Inferred from replica05 attached tabs and replica06 floating faces, rounded carriers and broad soft connectors.',
 'cutfield':'Inferred from replica05/10 lower-right chamfers, light figures and fine rising arrows.',
 'filament':'Inferred from replica03 editorial spacing and replica07 fine rounded outline frames; no new shadow material.',
 'portico':'Inferred from replica08 ruled editorial structure and replica13 navy/sand allocation panels.',
 'toggle-grid':'Inferred from replica09 thin grid rules, black headings and orange capsule emphasis.',
 'lamella':'Inferred from replica03 asymmetric leaf caps, vertical hairlines and quiet plot typography.',
 'rulemark':'Inferred from replica05 black table heads and replica09 circle/chevron direction markers.'}

def write(n,leaf,css,fixtures,description):
 D=R/n/n/'elements'/leaf;D.mkdir(parents=True,exist_ok=True);(D/'fixtures').mkdir(exist_ok=True)
 (D/'element.css').write_text('/* '+DESC[n]+'\n   '+leaf+' is absent from the replica; this is a new element in that measured language. */\n'+css+'\n')
 contract='code.block@1'if leaf=='code'else'delta.change@1';(D/'element.json').write_text(json.dumps({'schema':'rhetis.design-library-element-source/1','contract':contract,'registrations':{},'tokenDefaults':{}},indent=2));(D/'description.md').write_text(DESC[n]+' '+description+'\n')
 for name,(mini,markup)in fixtures.items():(D/'fixtures'/(name+'.html')).write_text('<!-- min: '+mini+' -->\n'+markup+'\n')

def delta(n):
 s='.delta[data-el="'+n+'-delta"]';css=f'''{s}{{box-sizing:border-box;position:relative;isolation:isolate;display:flex;flex-wrap:wrap;align-items:center;align-content:center;column-gap:16%;row-gap:var(--gap);width:100%;height:100%;min-width:0;min-height:0;container-type:size;padding:var(--gap);font-family:var(--font-display);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track);font-variant-numeric:tabular-nums;color:var(--ink)}}
{s}>.from,{s}>.to{{position:relative;display:flex;align-items:center;justify-content:center;min-width:0;min-height:0;max-width:100%;flex:1 1 calc((230px - 100%)*999);padding:var(--pad) var(--gap-sm);font-size:clamp(var(--type-20),calc(min(7.5cqw,17cqh)),var(--type-80));line-height:var(--figure-line);text-align:center;word-break:keep-all;text-wrap:balance;overflow-wrap:break-word}}
{s}>.from{{grid-column:1}}{s}>.to{{grid-column:3}}
{s}::before{{content:"";position:absolute;left:44%;top:50%;width:12%;height:var(--stroke);background:var(--ink)}}
{s}::after{{content:"";position:absolute;left:calc(56% - 9px);top:calc(50% - 5px);width:10px;height:10px;border-top:var(--stroke) solid var(--ink);border-right:var(--stroke) solid var(--ink);transform:rotate(45deg)}}
'''
 if n=='tide-tab':css+=f'''{s}>.from,{s}>.to{{min-height:42cqh;background:var(--n-1);border-radius:var(--radius);box-shadow:0 calc(var(--gap-sm)*.5) var(--gap-sm) color-mix(in srgb,var(--ink) 8%,transparent)}}{s}>.from{{color:var(--n-7)}}{s}>.to{{border-bottom:calc(var(--stroke)*3) solid var(--a2)}}{s}::before{{height:calc(var(--stroke)*4);border-radius:999px;background:linear-gradient(90deg,var(--a1),var(--a2))}}{s}::after{{border-width:calc(var(--stroke)*2);border-color:var(--a2)}}'''
 elif n=='cutfield':css+=f'''{s}{{font-weight:calc(var(--weight-display)*.625)}}{s}>.from,{s}>.to{{min-height:52cqh;clip-path:polygon(0 0,100% 0,100% calc(100% - min(var(--pad),8cqw,10cqh)),calc(100% - min(var(--pad),8cqw,10cqh)) 100%,0 100%)}}{s}>.from{{background:var(--n-2);color:var(--ink)}}{s}>.to{{background:var(--a1);color:var(--a1-on)}}{s}::before{{left:calc(50% - min(5cqw,19px));width:min(10cqw,38px);transform:rotate(-35deg);transform-origin:center}}{s}::after{{left:calc(50% + min(10cqw,38px)*.409576 - 4.6338px);top:calc(50% - min(10cqw,38px)*.286788 + 3.24464px);width:8px;height:8px;transform:translate(-50%,-50%) rotate(10deg)}}'''
 elif n=='filament':css+=f'''{s}{{color:var(--a1-8);font-weight:var(--weight-display)}}{s}>.from,{s}>.to{{min-height:min(50cqh,28cqw);border:var(--stroke) solid var(--a1-8);border-radius:50%;padding:var(--pad)}}{s}>.to{{background:var(--a1);color:var(--a1-on)}}{s}::before{{background:var(--a1-8)}}{s}::after{{border-color:var(--a1-8)}}'''
 elif n=='portico':css+=f'''{s}{{font-family:var(--font-body)}}{s}>.from,{s}>.to{{min-height:47cqh;border:var(--stroke) solid var(--n-4);border-radius:0}}{s}>.from{{background:var(--n-3)}}{s}>.to{{background:var(--a1);color:var(--a1-on)}}{s}::before{{background:var(--n-7)}}{s}::after{{border-color:var(--n-7)}}'''
 elif n=='toggle-grid':css+=f'''{s}{{border-bottom:var(--stroke) solid var(--ink);font-weight:var(--weight-display)}}{s}>.from{{border-bottom:var(--stroke) solid var(--ink)}}{s}>.to{{min-height:min(45cqh,28cqw);border:var(--stroke) solid var(--ink);border-radius:999px;background:var(--a1);color:var(--a1-on)}}'''
 elif n=='lamella':css+=f'''{s}>.from,{s}>.to{{min-height:40cqh;border-left:var(--stroke) solid var(--n-5);border-radius:0 var(--radius) 0 var(--radius);font-weight:var(--body-weight)}}{s}>.from{{background:var(--a1-2-soft)}}{s}>.to{{background:var(--a1);color:var(--a1-on)}}{s}::before{{background:var(--n-5)}}{s}::after{{border-color:var(--n-5)}}'''
 elif n=='rulemark':css+=f'''{s}>.from,{s}>.to{{min-height:48cqh;border:var(--stroke) solid var(--ink)}}{s}>.from{{background:var(--n-1)}}{s}>.to{{background:var(--ink);color:var(--page)}}{s}::before{{left:46%;width:8%;height:auto;aspect-ratio:1;transform:translateY(-50%);border-radius:50%;background:var(--ink)}}{s}::after{{left:calc(50% - 4px);border-color:var(--page);border-width:calc(var(--stroke)*2)}}'''
 css+=f'''\n@container(max-height:210px){{{s}>.from,{s}>.to{{padding:var(--gap-sm);font-size:clamp(var(--type-20),calc(min(6.8cqw,25cqh)),var(--type-48));min-height:55cqh}}}}
@container(max-width:230px){{{s}{{grid-template-columns:1fr;grid-template-rows:1fr 16% 1fr;padding:var(--gap-sm)}}{s}>.from{{grid-column:1;grid-row:1}}{s}>.to{{grid-column:1;grid-row:3}}{s}>.from,{s}>.to{{font-size:clamp(var(--type-18),calc(10cqw),var(--type-28));min-height:0;height:calc(50cqh - var(--gap)*1.5);padding:var(--gap-sm)}}{s}::before{{left:50%;top:calc(50% - var(--gap)*.5);height:var(--gap);width:var(--stroke);aspect-ratio:auto;border-radius:0;transform:none}}{s}::after{{left:50%;top:calc(50% + var(--gap)*.5 - 7.071px);width:10px;height:10px;transform:translate(-50%,-50%) rotate(135deg)}}}}
'''
 if n=='tide-tab':css+=f'{s}>.from,{s}>.to{{flex-basis:calc((230px - 100%)*999)}}@container(max-width:230px){{{s}::before{{width:calc(var(--stroke)*4);background:linear-gradient(180deg,var(--a1),var(--a2))}}}}'
 if n in ['portico','toggle-grid','rulemark']:css+=f'{s}{{padding:min(var(--gap),2%)}}@container(max-height:210px){{{s}>.from,{s}>.to{{min-height:max(55cqh,calc(2lh + var(--gap-sm)*2))}}}}@container(max-width:230px){{{s}>.from,{s}>.to{{min-height:0}}}}'
 if n=='rulemark':css+=f'@container(max-width:230px){{{s}::before{{left:50%;top:50%;width:min(16cqw,32px);height:auto;aspect-ratio:1;border-radius:50%;transform:translate(-50%,-50%)}}{s}::after{{left:50%;top:calc(50% - 2px);transform:translate(-50%,-50%) rotate(135deg);border-color:var(--page)}}}}'
 def fixture(a,b):return '<div class="delta" data-el="'+n+'-delta" style="grid-column:1 / span 12; grid-row:1 / span 6"><span class="from">'+escape(a)+'</span><span class="to">'+escape(b)+'</span></div>'
 write(n,'delta',css,{'hours':(('2x2' if n=='tide-tab'else '2x2 | 3x1'),fixture('18.4시간','11.2시간')),'long-units':(('2x2' if n=='tide-tab'else '2x2 | 3x1'),fixture('분기 184건','분기 297건'))},'Two figures occupy equal measured faces with a connector owned by their common root. Narrow portrait cells turn the pair downward; both figures stay visible.')

def code(n):
 s='.code[data-el="'+n+'-code"]';css=f'''{s}{{box-sizing:border-box;position:relative;isolation:isolate;display:grid;grid-template-rows:auto minmax(0,1fr);align-content:center;gap:var(--gap-sm);width:100%;height:100%;min-width:0;min-height:0;container-type:size;padding:min(var(--pad),2%);font-family:var(--{n}-code-font);font-weight:var(--body-weight);color:var(--ink);line-height:var(--body-line);letter-spacing:calc(var(--body-track)*0)}}
{s}:not(:has(>.name)){{grid-template-rows:minmax(0,1fr)}}
{s}>.name{{position:relative;z-index:1;display:flex;align-items:center;min-width:0;margin:0;font-family:var(--font-body);font-weight:var(--label-weight);font-size:clamp(var(--type-12),calc(min(2.5cqw,4.5cqh)),var(--type-22));line-height:var(--label-line);letter-spacing:var(--label-track);overflow-wrap:anywhere}}
{s}>.lines{{position:relative;z-index:1;display:flex;flex-direction:column;justify-content:center;min-width:0;min-height:0;counter-reset:rhetis-line;font-size:clamp(var(--type-12),calc(min(2.65cqw,4cqh)),var(--type-24));line-height:var(--body-line)}}
{s}>.lines>p{{position:relative;flex:none;min-width:0;margin:0;white-space:pre-wrap;word-break:keep-all;overflow-wrap:break-word;tab-size:2;font-size:inherit;line-height:inherit}}
{s}.numbered>.lines>p{{padding-left:3.4ch;counter-increment:rhetis-line}}
{s}.numbered>.lines>p::before{{content:counter(rhetis-line);position:absolute;left:0;width:2.4ch;text-align:right;color:var(--n-7);font-weight:var(--body-weight)}}
{s} .k{{color:var(--a1-7);font-weight:calc(var(--body-weight)*1.75)}}{s} .s{{color:var(--a2-7)}}{s} .n{{color:var(--a1-8)}}{s} .c{{color:var(--n-7)}}
'''
 if n=='tide-tab':css+=f'''{s}{{padding:min(calc(var(--pad)*.75),2%);border-radius:0 var(--radius) var(--radius) var(--radius);background:var(--n-1)}}{s}>.name{{justify-self:start;min-height:8cqh;max-width:100%;margin-top:calc(min(calc(var(--pad)*.75),2cqw)*-1);margin-left:calc(min(calc(var(--pad)*.75),2cqw)*-1);padding:var(--gap-sm) var(--gap);background:var(--a1);color:var(--a1-on);border-radius:var(--radius-sm) var(--radius-sm) 0 0}}'''
 elif n=='cutfield':css+=f'''{s}{{padding:min(var(--pad),2%);background:var(--n-1);clip-path:polygon(0 0,100% 0,100% calc(100% - var(--pad)),calc(100% - var(--pad)) 100%,0 100%)}}{s}>.name{{padding-bottom:var(--gap-sm);border-bottom:calc(var(--stroke)*2) solid var(--a1);color:var(--ink);font-weight:var(--name-weight)}}{s}.numbered>.lines{{border-left:var(--stroke) solid var(--n-4)}}'''
 elif n=='filament':css+=f'''{s}{{background:var(--page);border:var(--stroke) solid var(--a1-8);border-radius:var(--radius);color:var(--a1-8)}}{s}>.name{{font-style:italic;padding-bottom:var(--gap-sm);border-bottom:var(--stroke) solid var(--a1-8);font-weight:var(--body-weight)}}{s} .n{{color:var(--a1-8)}}{s}.numbered>.lines>p::before{{color:var(--a1-8)}}'''
 elif n=='portico':css+=f'''{s}{{border:var(--stroke) solid var(--n-4);padding-right:calc(var(--pad)*.5 + min(var(--pad),2%));background:var(--page)}}{s}::after{{content:"";position:absolute;right:0;top:0;bottom:0;width:calc(var(--pad)*.5);background:var(--a1)}}{s}>.name{{min-height:9cqh;margin:calc(min(var(--pad),2cqw)*-1) calc(min(var(--pad),2cqw)*-.5) 0 calc(min(var(--pad),2cqw)*-1);padding:var(--gap-sm) var(--pad);background:var(--n-3);font-weight:var(--name-weight)}}{s}>.lines>p{{border-bottom:var(--stroke) solid var(--n-3)}}'''
 elif n=='toggle-grid':css+=f'''{s}{{border:var(--stroke) solid var(--ink);border-bottom:calc(var(--stroke)*6) solid var(--ink);background:var(--page)}}{s}>.name{{min-height:10cqh;margin:calc(min(var(--pad),2cqw)*-1) calc(min(var(--pad),2cqw)*-1) 0;padding:var(--gap-sm) var(--pad);background:var(--ink);color:var(--page);font-family:var(--font-display);font-weight:var(--weight-display)}}{s}.numbered>.lines>p::before{{border-right:var(--stroke) solid var(--ink);color:var(--a1-7)}}{s}>.lines>p:nth-child(even){{background:var(--n-1)}}'''
 elif n=='lamella':css+=f'''{s}{{border-left:var(--stroke) solid var(--n-5);background:transparent}}{s}>.name{{justify-self:start;min-width:50%;max-width:100%;min-height:8cqh;margin:calc(min(var(--pad),2cqw)*-1) 0 0 calc(min(var(--pad),2cqw)*-1);padding:var(--gap-sm) var(--pad);border-radius:0 var(--radius) 0 var(--radius);background:var(--a1);color:var(--a1-on);font-weight:var(--body-weight)}}{s}.numbered>.lines>p::before{{border-right:var(--stroke) solid var(--n-4)}}'''
 elif n=='rulemark':css+=f'''{s}{{border:var(--stroke) solid var(--ink);background:var(--page)}}{s}>.name{{min-height:9cqh;margin:calc(min(var(--pad),2cqw)*-1) calc(min(var(--pad),2cqw)*-1) 0;padding:var(--gap-sm) var(--pad);background:var(--ink);color:var(--page)}}{s}>.lines>p{{border-bottom:var(--stroke) solid var(--n-4)}}{s}.numbered>.lines>p::before{{border-right:var(--stroke) solid var(--n-4)}}{s} .k,{s} .s,{s} .n{{color:var(--ink)}}'''
 css+=f'''\n@container(max-height:300px){{{s}{{padding:var(--gap-sm);gap:calc(var(--gap-sm)*.5)}}{s}>.name{{min-height:0;margin:0;padding:calc(var(--gap-sm)*.5) var(--gap-sm);font-size:var(--type-12)}}{s}>.lines{{font-size:var(--type-12);line-height:calc(var(--body-line)*.9)}}}}
@container(max-width:300px){{{s}{{padding:var(--gap-sm)}}{s}>.name{{margin:0;min-width:0;max-width:100%;padding:calc(var(--gap-sm)*.5) var(--gap-sm)}}{s}>.lines{{font-size:var(--type-12)}}}}
'''
 if n=='tide-tab':css+=f'{s}>.name{{margin-top:calc(min(calc(var(--pad)*.75),2cqw)*-1);margin-left:calc(min(calc(var(--pad)*.75),2cqw)*-1)}}'
 lines1=['<span class="c">// 거점의 포장량을 계산</span>','<span class="k">const</span> cargo = {','  hub: <span class="s">"서해"</span>,','  boxes: <span class="n">184</span>,','  rate: <span class="n">0.92</span>','};','<span class="k">const</span> packed = cargo.boxes * cargo.rate;','console.log(packed);']
 lines2=['<span class="c">-- 운송 묶음별 실적 조회</span>','<span class="k">SELECT</span>','  hub_key,','  SUM(box_qty) <span class="k">AS</span> packed_qty,','  AVG(lag_h) <span class="k">AS</span> mean_lag','<span class="k">FROM</span> cargo_day','<span class="k">WHERE</span> day_key &gt;= <span class="s">\'2098-04-01\'</span>','  <span class="k">AND</span> hub_key != <span class="s">\'보류\'</span>','<span class="k">GROUP BY</span> hub_key','<span class="k">HAVING</span> SUM(box_qty) &gt; <span class="n">140</span>','<span class="k">ORDER BY</span> mean_lag <span class="k">ASC</span>;','<span class="c">-- 평균 지연이 짧은 곳부터 점검</span>']
 def fixture(title,lines,numbered=False):return '<div class="code'+(' numbered'if numbered else'')+'" data-el="'+n+'-code" style="grid-column:1 / span 12; grid-row:1 / span 6"><p class="name">'+escape(title)+'</p><div class="lines">'+''.join('<p>'+l+'</p>'for l in lines)+'</div></div>'
 write(n,'code',css,{'cargo':(('3x2 | 2x3' if n in ['portico','toggle-grid']else '2x2'),fixture('포장량.js',lines1)),'hub-query-numbered':(('2x3' if n in ['cutfield','filament','lamella']else ('3x3 | 2x5' if n=='portico'else '3x3 | 2x4')),fixture('거점별 납기 점검용 묶음 조회.sql',lines2,True))},'A readable monospaced business snippet with its filename and optional true line counters. The header, enclosure and rules use this deck’s source material; token colours retain contrast in both modes. Narrow cells wrap at spaces without hiding source lines.')
if __name__=='__main__':
 for n in NAMES:delta(n);code(n)
 print('14 inferred element folders freshly authored')
